module benchmark/solution

export type Tree = Leaf | Node(Tree, int, Tree)

export pure func insert(t: Tree, x: int) -> Tree =
  match t {
    Leaf => Node(Leaf, x, Leaf),
    Node(l, v, r) =>
      if x < v then Node(insert(l, x), v, r)
      else if x > v then Node(l, v, insert(r, x))
      else t
  }

export pure func contains(t: Tree, x: int) -> bool =
  match t {
    Leaf => false,
    Node(l, v, r) =>
      if x == v then true
      else if x < v then contains(l, x)
      else contains(r, x)
  }

export pure func size(t: Tree) -> int =
  match t {
    Leaf => 0,
    Node(l, _, r) => size(l) + 1 + size(r)
  }

export pure func isBST(t: Tree, lo: int, hi: int) -> bool =
  match t {
    Leaf => true,
    Node(l, v, r) => v > lo && v < hi && isBST(l, lo, v) && isBST(r, v, hi)
  }

export pure func insertPreservesBST(x: int) -> bool =
  isBST(insert(insert(insert(Leaf, 5), 3), x), -999999, 999999)

export pure func insertThenFind(x: int) -> bool =
  contains(insert(insert(insert(Leaf, 5), 3), x), x)

export func main() -> () ! {IO} {
  let t = insert(insert(insert(Leaf, 5), 3), 7);
  println(show(size(t)));
  println(show(contains(t, 3)));
  println(show(contains(t, 4)));
  println(show(isBST(t, -999999, 999999)));
  println(show(insertPreservesBST(42)));
  println(show(insertThenFind(42)))
}

